<style scoped>
/* ===================== SCAR BACKGROUND RIG ===================== */
.scar-bg {
  --ink: #7a0e12;
  --ink-dim: #3c0507;
  --ink-bright: #d5262c;
  --ink-ember: #ff5b3c;
  --bg: #0b0505;

  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 100vh;
  height: 100svh;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
  background: var(--bg);
}

.scar-bg svg {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(78vw, 44.6vh);
  height: min(122vw, 66vh);
  width: min(78vw, 44.6svh);
  height: min(122vw, 66svh);
  transform: translate(-50%, -50%);
  overflow: visible;
}

.scar-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 42%, rgba(213, 38, 44, 0.16), transparent 58%);
}

/* base silhouette: exact geometry (lightly de-noised, see note in defs above) */
.glyph-fill .rune-mass-a,
.glyph-fill .rune-mass-b {
  fill: var(--ink);
  stroke: none;
}

.glyph-fill .rune-accent-a,
.glyph-fill .rune-accent-b {
  fill: var(--ink-dim);
  stroke: none;
}

/* glowing energy tracing along the same exact paths, via <use> so geometry can never drift */
.trace-line use {
  fill: none;
  stroke: var(--ink-bright);
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* grain / stipple ember dust, thinned for a lighter, less noisy texture */
.rune-dust .grain-coarse {
  fill: var(--ink-bright);
  opacity: 0.55;
}

.rune-dust .grain-fine {
  fill: var(--ink-ember);
  opacity: 0.38;
}

/* ===================== ANIMATION (opt-in only) ===================== */
@media (prefers-reduced-motion: no-preference) {

  .ritual-scar {
    transform-origin: 540px 841.5px;
    animation: scar-breathe 15s ease-in-out infinite;
    will-change: transform;
  }

  @keyframes scar-breathe {
    0% {
      transform: rotate(0deg) scale(1);
    }

    25% {
      transform: rotate(0.35deg) scale(1.006);
    }

    50% {
      transform: rotate(-0.2deg) scale(0.998);
    }

    75% {
      transform: rotate(0.4deg) scale(1.004);
    }

    100% {
      transform: rotate(0deg) scale(1);
    }
  }

  /* the base silhouette glows brighter in step with its own line being "written" */
  @keyframes ember-pulse {
    0% {
      opacity: 0.35;
      filter: drop-shadow(0 0 2px var(--ink-bright)) drop-shadow(0 0 4px var(--ink-dim));
    }

    40% {
      opacity: 0.95;
      filter: drop-shadow(0 0 10px var(--ink-bright)) drop-shadow(0 0 22px var(--ink-ember));
    }

    60% {
      opacity: 1;
      filter: drop-shadow(0 0 14px var(--ink-bright)) drop-shadow(0 0 30px var(--ink-ember));
    }

    100% {
      opacity: 0.35;
      filter: drop-shadow(0 0 2px var(--ink-bright)) drop-shadow(0 0 4px var(--ink-dim));
    }
  }

  .rune-mass-a {
    animation: ember-pulse 12s ease-in-out infinite;
  }

  .rune-mass-b {
    animation: ember-pulse 14s ease-in-out infinite -2s;
  }

  .rune-accent-a {
    animation: ember-pulse 9s ease-in-out infinite -4s;
  }

  .rune-accent-b {
    animation: ember-pulse 10.5s ease-in-out infinite -6s;
  }

  /* written, then erased, then written again — a single continuous breath */
  @keyframes trace-breathe {
    0% {
      stroke-dashoffset: 1;
      opacity: 0;
    }

    12% {
      opacity: 0.9;
    }

    45% {
      stroke-dashoffset: 0;
      opacity: 1;
    }

    60% {
      stroke-dashoffset: 0;
      opacity: 1;
    }

    88% {
      opacity: 0.9;
    }

    100% {
      stroke-dashoffset: -1;
      opacity: 0;
    }
  }

  .trace-line use {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    animation-name: trace-breathe;
    animation-timing-function: cubic-bezier(.45, 0, .4, 1);
    animation-iteration-count: infinite;
    will-change: stroke-dashoffset, opacity;
  }

  .trace-mass-a {
    animation-duration: 12s;
    animation-delay: 0s;
  }

  .trace-mass-b {
    animation-duration: 14s;
    animation-delay: -2s;
  }

  .trace-accent-a {
    animation-duration: 9s;
    animation-delay: -4s;
  }

  .trace-accent-b {
    animation-duration: 10.5s;
    animation-delay: -6s;
  }

  /* ember / grain dust shimmer */
  @keyframes dust-shimmer {

    0%,
    100% {
      opacity: 0.4;
    }

    50% {
      opacity: 1;
    }
  }

  .rune-dust {
    animation: dust-shimmer 6s ease-in-out infinite;
  }
}

/* ================================================================== */
</style>
